#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include "lib/xxhash.h"
#define FUZZ_rotl32(x, r) (((x) << (r)) | ((x) >> (32 - (r))))
static uint32_t FUZZ_rand(uint32_t *state) { uint32_t rand32=*state; rand32*=2654435761U; rand32+=2246822519U; rand32=FUZZ_rotl32(rand32,13); *state=rand32; return rand32 >> 5; }
int main(int argc, char**argv){ int max=argc>1?atoi(argv[1]):100; for(uint64_t x=0;x<0x100000000ULL;x++){ unsigned char b[4]={x,x>>8,x>>16,x>>24}; uint32_t s=XXH32(b,4,0); uint32_t r=FUZZ_rand(&s); uint32_t cap=r%(max+1); if(cap== (argc>2?atoi(argv[2]):max)){ printf("%02x%02x%02x%02x seed=%u r=%u cap=%u\n",b[0],b[1],b[2],b[3],XXH32(b,4,0),r,cap); return 0;} } }
EOF
gcc -O3 -I. /tmp/seedcalc.c lib/xxhash.c -o /tmp/seedcalc
